"aprepitant":{"s":"696f9e80-9cae-403b-de9e-078343ce4713","d":"2024-07-05","b":"Emend (aprepitant)","m":"Merck Sharp & Dohme LLC","r":"ORAL","q":[["Adult","…EMEND capsules in adults and pediatric patients 12 years of age and older: is 125 mg on Day 1 and 80 mg on Days 2 and 3."],["Timing","Administer EMEND 1 hour prior to chemotherapy on Days 1, 2, and 3."],["Pediatric","Dosing of EMEND for oral suspension is based on weight, to a maximum of 125 mg on Day 1 and 80 mg on Days 2 and 3."]],"nl":0},
"fosaprepitant":{"s":"ffee61d1-c1c6-4224-871c-ab7ff6cd01e5","d":"2024-06-19","b":"Fosaprepitant for injection (fosaprepitant dimeglumine)","m":"Fresenius Kabi USA, LLC","r":"INTRAVENOUS","q":[["Adult","Fosaprepitant for injection 150 mg on Day 1 as an intravenous infusion over 20 to 30 minutes."],["Timing","Complete the infusion approximately 30 minutes prior to chemotherapy."],["Pediatric 2 to less than 12 years","4 mg/kg (maximum dose 150 mg) intravenously over 60 minutes"]],"nl":0},
"palonosetron":{"s":"9132366b-b808-46c9-b167-c1900bc116b3","d":"2020-12-29","b":"Palonosetron Hydrochloride Injection","m":"Fresenius Kabi USA, LLC","r":"INTRAVENOUS","q":[["Adult CINV","Infuse over 30 seconds beginning approximately 30 minutes before the start of chemotherapy"],["Pediatric CINV","20 micrograms per kilogram (maximum 1.5 mg) as a single dose"],["PONV","The recommended adult dosage is 0.075 mg as a single intravenous dose administered over 10 seconds immediately before the induction of anesthesia."]],"nl":0},
"granisetron":{"s":"dddc8714-383f-4bc5-a468-ae89dbc802b4","d":"2022-11-15","b":"Granisetron Hydrochloride Injection","m":"Fresenius Kabi USA, LLC","r":"INTRAVENOUS","q":[["Adult","10 mcg/kg administered intravenously within 30 minutes before initiation of chemotherapy"],["Pediatric","The recommended dose in pediatric patients 2 to 16 years of age is 10 mcg/kg"]],"nl":0},
"netupitant-palonosetron":{"s":"8e47618e-af46-4d82-94e8-1507c042252d","d":"2026-06-23","b":"Akynzeo (netupitant and palonosetron)","m":"Helsinn Therapeutics (U.S.), Inc.","r":"ORAL","q":[["Adult","The recommended dosage is one AKYNZEO capsule administered 1 hour prior to the start of chemotherapy, with or without food."],["Hepatic","Avoid use of AKYNZEO in patients with severe hepatic impairment"],["Renal","Avoid use of AKYNZEO in patients with severe renal impairment or end-stage renal disease"]],"nl":0}
